#include<bits/stdc++.h>

using namespace std;

long long sum(long long l,long long r,long long cnt){
  long long res=(l+r);
  res*=cnt;
  return res/2;
}

int main(){
  int t;
  cin >> t;
  for(int cs=0;cs<t;cs++){
    long long n,m;;
    cin >> n >> m;
    vector<long long> a(n),y(n);
    for(int i=0;i<n;i++){cin >> a[i] >> y[i];}

    long long cv=0,cx=0,res=-8e18;
    for(int i=0;i<n;i++){
      long long vl=cv+a[i];
      long long vr=cv+a[i]*y[i];
      if(a[i]!=0){
        if(vl>=0 && vr<=0){
          long long pt=(-cv)/a[i];
          res=max(res,cx+sum(vl,cv+a[i]*pt,pt));
        }
      }
      cv=vr;
      res=max(res,cx+vl);
      cx+=sum(vl,vr,y[i]);
      res=max(res,cx);
    }
    cout << res << '\n';
  }
}
